const DICTS = { en, fr, mcr }

export function translate(lang, key, params) {
  let s = DICTS[lang]?.[key] ?? en[key] ?? key
  if (params) for (const [k, v] of Object.entries(params)) s = s.replaceAll(`{${k}}`, v)
  return s
}

export const LangContext = createContext({ lang: 'en', t: (k, p) => translate('en', k, p) })
export const useT = () => useContext(LangContext)

// Pick the right language from a {en, fr, mcr} object (used for alerts and samples)
export const pick = (obj, lang) => (obj && typeof obj === 'object' && !Array.isArray(obj) ? obj[lang] ?? obj.en : obj)

// Remember the language before the user has an account
const LK = 'moniguard:lang'
export function savedLang() {
  try { const l = localStorage.getItem(LK); if (DICTS[l]) return l } catch { /* ignore */ }
  const nav = (navigator.language || '').slice(0, 2)
  return nav === 'fr' ? 'fr' : 'en'
}
export function rememberLang(l) { try { localStorage.setItem(LK, l) } catch { /* ignore */ } }
